def versuche_bis(ziel, zahlen):
    for i, z in enumerate(zahlen):
        if z == ziel:
            return i + 1
    return -1

def cross_sum(nbr: int) -> int:
    """Returns the cross sum (sum of digits) of nbr."""
    summe = 0
    for ziffer in str(nbr):
        summe += int(ziffer)
    return summe

def checkprime(number: int) -> bool:
    """Returns True if number is a prime number."""
    if number < 2:
        return False
    for teiler in range(2, number):
        if number % teiler == 0:
            return False
    return True

def vowel_stats(text: str) -> dict:
    """Counts the vowels a, e, i, o, u in text (case-insensitive)."""
    stats = {"a": 0, "e": 0, "i": 0, "o": 0, "u": 0}
    for zeichen in text.lower():
        if zeichen in stats:
            stats[zeichen] += 1
    return stats

